import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { Carousel, Slide, SlideContent, ExportSettings, PillarId } from '@/types/index';
import { DecoratorConfig } from '@/types/decorators';
import { titanArc, ArcTemplate } from '@/config/arc-templates/titan-arc';
import { StyleTemplateId } from '@/types/styles';
import type { ElementPosition, PositionedContent, ImageConfig, ContentFieldType } from '@/types/slide-subtypes';

interface CarouselPreset {
  id: string;
  name: string;
  description?: string;
  thumbnail?: string;
  carousel: Carousel;
  createdAt: string;
  updatedAt: string;
}

interface CarouselState {
  carousel: Carousel | null;
  selectedSlideId: string | null;
  exportSettings: ExportSettings;
  presets: CarouselPreset[];

  // Selectors
  getSlideById: (id: string) => Slide | undefined;
  getSelectedSlide: () => Slide | undefined;
  getSlidesByType: (type: Slide['type']) => Slide[];
  hasSlides: () => boolean;
  getSlideCount: () => number;
  getPresetById: (id: string) => CarouselPreset | undefined;

  // Actions
  createCarousel: (name: string, pillar: PillarId) => void;
  loadCarousel: (carousel: Carousel) => void;
  setPillar: (pillar: PillarId) => void;

  // Slide actions
  addSlide: (slide: Omit<Slide, 'id' | 'order'>) => void;
  updateSlide: (id: string, content: Partial<SlideContent>) => void;
  updateSlideStyle: (id: string, style: Partial<Slide['style']>) => void;
  updateSlideCTA: (id: string, cta: Partial<Slide['cta']>) => void;
  updateSlideType: (id: string, type: Slide['type']) => void;
  updateSlideSubType: (id: string, subType: string) => void;
  updateElementPosition: (id: string, field: ContentFieldType, position: ElementPosition) => void;
  updateElementAlignment: (id: string, field: ContentFieldType, alignment: 'left' | 'center' | 'right' | 'justify') => void;
  updateImageConfig: (id: string, imageConfig: ImageConfig) => void;
  duplicateSlide: (id: string) => void;
  clearSlideContent: (id: string) => void;
  updateAllSlidesDecoratorConfig: (decoratorConfig: Partial<DecoratorConfig>) => void;
  updateAllSlidesSettings: (template?: StyleTemplateId, visualTreatment?: any, decoratorConfig?: Partial<DecoratorConfig>) => void;
  removeSlide: (id: string) => void;
  reorderSlides: (activeId: string, overId: string) => void;
  selectSlide: (id: string | null) => void;

  // Template actions
  applyTemplate: (template: ArcTemplate) => void;

  // Export actions
  setExportSettings: (settings: Partial<ExportSettings>) => void;

  // Preset actions
  savePreset: (name: string, description?: string) => void;
  loadPreset: (presetId: string) => void;
  deletePreset: (presetId: string) => void;
  updatePreset: (presetId: string, name?: string, description?: string) => void;

  // Utility
  reset: () => void;
}

const generateId = () => Math.random().toString(36).substring(2, 11);

const defaultExportSettings: ExportSettings = {
  pixelRatio: 2,
  format: 'png',
  quality: 1,
};

export const useCarouselStore = create<CarouselState>()(
  persist(
    (set, get) => ({
      carousel: null,
      selectedSlideId: null,
      exportSettings: defaultExportSettings,
      presets: [],

      // Selectors
      getSlideById: (id) => {
        const { carousel } = get();
        return carousel?.slides.find((slide) => slide.id === id);
      },

      getSelectedSlide: () => {
        const { carousel, selectedSlideId } = get();
        if (!carousel || !selectedSlideId) return undefined;
        return carousel.slides.find((slide) => slide.id === selectedSlideId);
      },

      getSlidesByType: (type) => {
        const { carousel } = get();
        if (!carousel) return [];
        return carousel.slides.filter((slide) => slide.type === type);
      },

      hasSlides: () => {
        const { carousel } = get();
        return carousel ? carousel.slides.length > 0 : false;
      },

      getSlideCount: () => {
        const { carousel } = get();
        return carousel ? carousel.slides.length : 0;
      },

      getPresetById: (id) => {
        const { presets } = get();
        return presets.find((preset) => preset.id === id);
      },

      createCarousel: (name, pillar) => {
        const now = new Date().toISOString();
        const carousel: Carousel = {
          id: generateId(),
          name,
          pillar,
          slides: [],
          decoratorConfig: {
            logo: {
              enabled: true,
              position: 'top-right',
              size: 80,
              opacity: 1,
              imageUrl: '/default-logo.png',
              blendMode: 'normal',
            },
          },
          createdAt: now,
          updatedAt: now,
        };
        set({ carousel, selectedSlideId: null });
      },

      loadCarousel: (carousel) => {
        set({ carousel, selectedSlideId: carousel.slides[0]?.id || null });
      },

      setPillar: (pillar) => {
        const { carousel } = get();
        if (carousel) {
          set({
            carousel: {
              ...carousel,
              pillar,
              updatedAt: new Date().toISOString(),
            },
          });
        }
      },

      addSlide: (slideData) => {
        const { carousel } = get();
        if (!carousel) return;

        const newSlide: Slide = {
          ...slideData,
          id: generateId(),
          order: carousel.slides.length,
          style: {
            ...slideData.style,
            decoratorConfig: {}, // Initialize empty decorator config
          },
        };

        set({
          carousel: {
            ...carousel,
            slides: [...carousel.slides, newSlide],
            updatedAt: new Date().toISOString(),
          },
          selectedSlideId: newSlide.id,
        });
      },

      updateSlide: (id, content) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id
                ? { ...slide, content: { ...slide.content, ...content } }
                : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateSlideStyle: (id, style) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id
                ? {
                    ...slide,
                    style: {
                      ...slide.style,
                      ...style,
                      // Ensure decoratorConfig is properly merged
                      decoratorConfig: {
                        ...(slide.style?.decoratorConfig || {}),
                        ...((style as any)?.decoratorConfig || {}),
                      },
                    },
                  }
                : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateSlideCTA: (id, cta) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id
                ? { ...slide, cta: { ...slide.cta, ...cta } as Slide['cta'] }
                : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateSlideType: (id, type) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id ? { ...slide, type } : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateSlideSubType: (id, subType) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id ? { ...slide, subType } : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateElementPosition: (id, field, position) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) => {
              if (slide.id !== id) return slide;

              const currentContent = slide.content[field];
              const updatedContent: PositionedContent<any> =
                typeof currentContent === 'object' && currentContent !== null && 'value' in currentContent
                  ? { ...currentContent, position }
                  : { value: currentContent, position };

              return {
                ...slide,
                content: {
                  ...slide.content,
                  [field]: updatedContent,
                },
              };
            }),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateElementAlignment: (id, field, alignment) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) => {
              if (slide.id !== id) return slide;

              const currentContent = slide.content[field];
              const currentPosition: ElementPosition =
                typeof currentContent === 'object' && currentContent !== null && 'value' in currentContent
                  ? (currentContent as any).position || { mode: 'auto', alignment: alignment }
                  : { mode: 'auto', alignment: alignment };

              const updatedContent: PositionedContent<any> =
                typeof currentContent === 'object' && currentContent !== null && 'value' in currentContent
                  ? { ...currentContent, position: { ...currentPosition, alignment } }
                  : { value: currentContent, position: { ...currentPosition, alignment } };

              return {
                ...slide,
                content: {
                  ...slide.content,
                  [field]: updatedContent,
                },
              };
            }),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateImageConfig: (id, imageConfig) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id
                ? { ...slide, content: { ...slide.content, imageConfig } }
                : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      duplicateSlide: (id) => {
        const { carousel } = get();
        if (!carousel) return;

        const slideToDuplicate = carousel.slides.find((slide) => slide.id === id);
        if (!slideToDuplicate) return;

        const duplicatedSlide: Slide = {
          ...slideToDuplicate,
          id: generateId(),
          order: carousel.slides.length,
        };

        set({
          carousel: {
            ...carousel,
            slides: [...carousel.slides, duplicatedSlide],
            updatedAt: new Date().toISOString(),
          },
        });
      },

      clearSlideContent: (id) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) =>
              slide.id === id
                ? {
                    ...slide,
                    content: {},
                  }
                : slide
            ),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateAllSlidesDecoratorConfig: (decoratorConfig) => {
        const { carousel } = get();
        if (!carousel) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) => ({
              ...slide,
              style: {
                ...slide.style,
                decoratorConfig: { ...decoratorConfig },
              },
            })),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      updateAllSlidesSettings: (template, visualTreatment, decoratorConfig) => {
        const { carousel, selectedSlideId } = get();
        if (!carousel) return;

        // Get settings from currently selected slide if not provided
        const currentSlide = carousel.slides.find(s => s.id === selectedSlideId);
        if (!currentSlide) return;

        set({
          carousel: {
            ...carousel,
            slides: carousel.slides.map((slide) => ({
              ...slide,
              style: {
                ...slide.style,
                // Apply template if provided, otherwise use current slide's template
                template: template ?? currentSlide.style?.template,
                // Apply visual treatment if provided, otherwise use current slide's treatment
                visualTreatment: visualTreatment ?? currentSlide.style?.visualTreatment,
                // Apply decorator config if provided
                decoratorConfig: decoratorConfig ?? currentSlide.style?.decoratorConfig,
              },
            })),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      removeSlide: (id) => {
        const { carousel, selectedSlideId } = get();
        if (!carousel) return;

        const newSlides = carousel.slides
          .filter((slide) => slide.id !== id)
          .map((slide, index) => ({ ...slide, order: index }));

        set({
          carousel: {
            ...carousel,
            slides: newSlides,
            updatedAt: new Date().toISOString(),
          },
          selectedSlideId:
            selectedSlideId === id
              ? newSlides[0]?.id || null
              : selectedSlideId,
        });
      },

      reorderSlides: (activeId, overId) => {
        const { carousel } = get();
        if (!carousel) return;

        const activeIndex = carousel.slides.findIndex((s) => s.id === activeId);
        const overIndex = carousel.slides.findIndex((s) => s.id === overId);

        if (activeIndex === -1 || overIndex === -1) return;

        const newSlides = [...carousel.slides];
        const [removed] = newSlides.splice(activeIndex, 1);
        newSlides.splice(overIndex, 0, removed);

        set({
          carousel: {
            ...carousel,
            slides: newSlides.map((slide, index) => ({ ...slide, order: index })),
            updatedAt: new Date().toISOString(),
          },
        });
      },

      selectSlide: (id) => {
        set({ selectedSlideId: id });
      },

      applyTemplate: (template) => {
        const { carousel } = get();
        if (!carousel) return;

        const slides: Slide[] = template.slides.map((slideTemplate, index) => ({
          id: generateId(),
          type: slideTemplate.type,
          content: { ...slideTemplate.defaultContent },
          order: index,
        }));

        set({
          carousel: {
            ...carousel,
            slides,
            updatedAt: new Date().toISOString(),
          },
          selectedSlideId: slides[0]?.id || null,
        });
      },

      setExportSettings: (settings) => {
        set({
          exportSettings: { ...get().exportSettings, ...settings },
        });
      },

      // Preset actions
      savePreset: (name, description) => {
        const { carousel, presets } = get();
        if (!carousel) {
          console.error('Cannot save preset: No carousel loaded');
          return;
        }

        const now = new Date().toISOString();
        const preset: CarouselPreset = {
          id: generateId(),
          name,
          description,
          carousel: JSON.parse(JSON.stringify(carousel)), // Deep clone
          createdAt: now,
          updatedAt: now,
        };

        set({
          presets: [...presets, preset],
        });
      },

      loadPreset: (presetId) => {
        const { presets } = get();
        const preset = presets.find((p) => p.id === presetId);

        if (!preset) {
          console.error('Preset not found:', presetId);
          return;
        }

        // Deep clone the carousel to avoid reference issues
        const loadedCarousel = JSON.parse(JSON.stringify(preset.carousel));

        set({
          carousel: loadedCarousel,
          selectedSlideId: loadedCarousel.slides[0]?.id || null,
        });
      },

      deletePreset: (presetId) => {
        const { presets } = get();
        set({
          presets: presets.filter((p) => p.id !== presetId),
        });
      },

      updatePreset: (presetId, name, description) => {
        const { presets } = get();
        set({
          presets: presets.map((p) =>
            p.id === presetId
              ? {
                  ...p,
                  ...(name && { name }),
                  ...(description !== undefined && { description }),
                  updatedAt: new Date().toISOString(),
                }
              : p
          ),
        });
      },

      reset: () => {
        set({
          carousel: null,
          selectedSlideId: null,
          exportSettings: defaultExportSettings,
          presets: [],
        });
      },
    }),
    {
      name: 'carousel-storage',
      partialize: (state) => ({
        carousel: state.carousel,
        exportSettings: state.exportSettings,
        presets: state.presets,
      }),
    }
  )
);
