import { create } from 'zustand';
import { CanvasElement, Transform } from '@/types/canvas-elements';

/**
 * Canvas state interface
 */
interface CanvasState {
  // Elements
  elements: Map<string, CanvasElement>;

  // Selection
  selectedIds: string[];

  // View state
  zoom: number;
  pan: { x: number; y: number };

  // Tool state
  activeTool: 'select' | 'text' | 'image' | 'hand';

  // Actions
  addElement: (element: CanvasElement) => void;
  updateElement: (id: string, updates: Partial<CanvasElement>) => void;
  deleteElement: (id: string) => void;
  deleteSelected: () => void;
  selectElement: (id: string, multiSelect?: boolean) => void;
  deselectAll: () => void;
  setZoom: (zoom: number) => void;
  setPan: (pan: { x: number; y: number }) => void;
  setActiveTool: (tool: 'select' | 'text' | 'image' | 'hand') => void;

  // History (for undo/redo)
  history: CanvasElement[][];
  historyIndex: number;
  undo: () => void;
  redo: () => void;
  saveToHistory: () => void;

  // Selection persistence
  persistSelection: () => void;
  restoreSelection: () => void;
  clearSelectionPersistence: () => void;

  // Clear all elements
  clearElements: () => void;
}

/**
 * Canvas store using Zustand
 */
export const useCanvasStore = create<CanvasState>((set, get) => ({
  // Initial state
  elements: new Map(),
  selectedIds: [],
  zoom: 1,
  pan: { x: 0, y: 0 },
  activeTool: 'select',
  history: [],
  historyIndex: -1,

  /**
   * Add an element to the canvas
   */
  addElement: (element: CanvasElement) => {
    set((state) => {
      const newElements = new Map(state.elements);
      newElements.set(element.id, element);
      return { elements: newElements };
    });
    get().saveToHistory();
  },

  /**
   * Update an existing element
   */
  updateElement: (id: string, updates: Partial<CanvasElement>) => {
    set((state) => {
      const element = state.elements.get(id);
      if (!element) return state;

      const updatedElement = { ...element, ...updates };
      const newElements = new Map(state.elements);
      newElements.set(id, updatedElement);

      return { elements: newElements };
    });
    get().saveToHistory();
  },

  /**
   * Delete an element by ID
   */
  deleteElement: (id: string) => {
    set((state) => {
      const newElements = new Map(state.elements);
      newElements.delete(id);

      // Remove from selection if selected
      const newSelectedIds = state.selectedIds.filter((selectedId) => selectedId !== id);

      return { elements: newElements, selectedIds: newSelectedIds };
    });
    get().saveToHistory();
    get().persistSelection(); // Update persisted selection
  },

  /**
   * Delete all selected elements
   */
  deleteSelected: () => {
    set((state) => {
      const newElements = new Map(state.elements);
      state.selectedIds.forEach((id) => {
        newElements.delete(id);
      });

      return { elements: newElements, selectedIds: [] };
    });
    get().saveToHistory();
    get().persistSelection(); // Update persisted selection
  },

  /**
   * Select an element
   */
  selectElement: (id: string, multiSelect = false) => {
    set((state) => {
      if (!multiSelect) {
        return { selectedIds: [id] };
      }

      // Toggle selection if multi-select
      const isSelected = state.selectedIds.includes(id);
      if (isSelected) {
        return {
          selectedIds: state.selectedIds.filter((selectedId) => selectedId !== id),
        };
      } else {
        return { selectedIds: [...state.selectedIds, id] };
      }
    });
    
    // Save selection state to localStorage (selection persistence)
    get().persistSelection();
  },

  /**
   * Deselect all elements
   */
  deselectAll: () => {
    set({ selectedIds: [] });
    get().persistSelection(); // Update persisted selection
  },

  /**
   * Set zoom level
   */
  setZoom: (zoom: number) => {
    set({ zoom });
  },

  /**
   * Set pan position
   */
  setPan: (pan: { x: number; y: number }) => {
    set({ pan });
  },

  /**
   * Set active tool
   */
  setActiveTool: (tool: 'select' | 'text' | 'image' | 'hand') => {
    set({ activeTool: tool });
  },

  /**
   * Save current state to history
   */
  saveToHistory: () => {
    set((state) => {
      const currentElements = Array.from(state.elements.values());

      // Check if state has changed from last history entry
      const lastHistoryEntry = state.history[state.historyIndex];
      const hasChanged = lastHistoryEntry
        ? JSON.stringify(currentElements) !== JSON.stringify(lastHistoryEntry)
        : true;

      if (!hasChanged) {
        return state; // Don't save if state hasn't changed
      }

      // Remove any future history if we're not at the end
      const newHistory = state.history.slice(0, state.historyIndex + 1);
      newHistory.push(currentElements);

      // Limit history to 50 states
      if (newHistory.length > 50) {
        newHistory.shift();
      }

      return {
        history: newHistory,
        historyIndex: newHistory.length - 1,
      };
    });
  },

  /**
   * Undo last action
   */
  undo: () => {
    set((state) => {
      if (state.historyIndex <= 0) return state;

      const newIndex = state.historyIndex - 1;
      const previousElements = state.history[newIndex];

      const newElements = new Map<string, CanvasElement>();
      previousElements.forEach((element) => {
        newElements.set(element.id, element);
      });

      return {
        elements: newElements,
        historyIndex: newIndex,
      };
    });
  },

  /**
   * Redo last undone action
   */
  redo: () => {
    set((state) => {
      if (state.historyIndex >= state.history.length - 1) return state;

      const newIndex = state.historyIndex + 1;
      const nextElements = state.history[newIndex];

      const newElements = new Map<string, CanvasElement>();
      nextElements.forEach((element) => {
        newElements.set(element.id, element);
      });

      return {
        elements: newElements,
        historyIndex: newIndex,
      };
    });
  },

  /**
   * Persist selection state to localStorage
   */
  persistSelection: () => {
    const state = get();
    try {
      localStorage.setItem('canvas-selection', JSON.stringify(state.selectedIds));
    } catch (error) {
      console.error('Failed to persist selection:', error);
    }
  },

  /**
   * Restore selection state from localStorage
   */
  restoreSelection: () => {
    try {
      const savedSelection = localStorage.getItem('canvas-selection');
      if (savedSelection) {
        const selectedIds = JSON.parse(savedSelection) as string[];
        
        // Filter out IDs that no longer exist in elements
        const validSelection = selectedIds.filter((id) => 
          get().elements.has(id)
        );
        
        set({ selectedIds: validSelection });
      }
    } catch (error) {
      console.error('Failed to restore selection:', error);
    }
  },

/**
 * Clear selection persistence
 */
clearSelectionPersistence: () => {
  try {
    localStorage.removeItem('canvas-selection');
  } catch (error) {
    console.error('Failed to clear selection persistence:', error);
  }
},

/**
 * Clear all elements from the canvas
 */
clearElements: () => {
  set({
    elements: new Map(),
    selectedIds: [],
  });
},
}));