'use client';

import React, { useState, useEffect } from 'react';
import { useCarouselStore } from '@/store/carousel-store';
import { CarouselEditor } from '@/components/editor/CarouselEditor';
import { ExportDialog } from '@/components/export/ExportDialog';
import { PillarId } from '@/types/index';
import { pillarList } from '@/config/pillars';
import { Download, Plus, Save, FolderOpen } from 'lucide-react';

export default function HomePage() {
  const { carousel, createCarousel, reset } = useCarouselStore();
  const [showExport, setShowExport] = useState(false);
  const [showNewCarousel, setShowNewCarousel] = useState(false);
  const [newName, setNewName] = useState('');
  const [newPillar, setNewPillar] = useState<PillarId>('p1');

  // Auto-show new carousel dialog if none exists
  useEffect(() => {
    if (!carousel) {
      setShowNewCarousel(true);
    }
  }, [carousel]);

  const handleCreate = () => {
    if (!newName.trim()) return;
    createCarousel(newName.trim(), newPillar);
    setShowNewCarousel(false);
    setNewName('');
  };

  const handleExportJSON = () => {
    if (!carousel) return;

    const data = JSON.stringify(carousel, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${carousel.name}_carousel.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImportJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        useCarouselStore.getState().loadCarousel(data);
      } catch (error) {
        alert('Invalid JSON file');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="h-screen flex flex-col overflow-hidden">
      {/* Header */}
      <header className="flex-shrink-0 border-b border-white/10 px-6 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <h1 className="text-xl font-bold bg-gradient-to-r from-blue-400 to-purple-400 bg-clip-text text-transparent">
              Carousel Generator
            </h1>
            {carousel && (
              <span className="text-white/60 text-sm">
                {carousel.name}
              </span>
            )}
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => setShowNewCarousel(true)}
              className="flex items-center gap-2 px-4 py-2 text-sm text-white/70 hover:text-white hover:bg-white/5 rounded-lg transition-colors"
            >
              <Plus className="w-4 h-4" />
              New
            </button>

            <label className="flex items-center gap-2 px-4 py-2 text-sm text-white/70 hover:text-white hover:bg-white/5 rounded-lg transition-colors cursor-pointer">
              <FolderOpen className="w-4 h-4" />
              Import
              <input
                type="file"
                accept=".json"
                onChange={handleImportJSON}
                className="hidden"
              />
            </label>

            {carousel && (
              <>
                <button
                  onClick={handleExportJSON}
                  className="flex items-center gap-2 px-4 py-2 text-sm text-white/70 hover:text-white hover:bg-white/5 rounded-lg transition-colors"
                >
                  <Save className="w-4 h-4" />
                  Save JSON
                </button>

                <button
                  onClick={() => setShowExport(true)}
                  className="flex items-center gap-2 px-4 py-2 text-sm bg-gradient-to-r from-blue-500 to-purple-500 text-white rounded-lg hover:opacity-90 transition-opacity"
                >
                  <Download className="w-4 h-4" />
                  Export PNG
                </button>
              </>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 p-6 overflow-hidden min-h-0">
        <CarouselEditor />
      </main>

      {/* Export Dialog */}
      <ExportDialog isOpen={showExport} onClose={() => setShowExport(false)} />

      {/* New Carousel Dialog */}
      {showNewCarousel && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80">
          <div className="bg-gray-900 rounded-2xl w-full max-w-md p-6">
            <h2 className="text-xl font-bold text-white mb-6">
              Create New Carousel
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-white/70 mb-2">
                  Carousel Name
                </label>
                <input
                  type="text"
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  placeholder="My Awesome Carousel"
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/40 focus:outline-none focus:border-white/40"
                  autoFocus
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-white/70 mb-2">
                  Pillar Theme
                </label>
                <div className="grid grid-cols-3 gap-2">
                  {pillarList.map((pillar) => (
                    <button
                      key={pillar.id}
                      onClick={() => setNewPillar(pillar.id)}
                      className={`px-3 py-2 rounded-lg text-sm transition-all border-2 ${
                        newPillar === pillar.id
                          ? 'border-white text-white'
                          : 'border-transparent text-white/60 hover:text-white hover:bg-white/5'
                      }`}
                      style={{
                        backgroundColor:
                          newPillar === pillar.id
                            ? pillar.primaryColor + '20'
                            : undefined,
                      }}
                    >
                      <span
                        className="inline-block w-2 h-2 rounded-full mr-2"
                        style={{ backgroundColor: pillar.primaryColor }}
                      />
                      {pillar.name}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              {carousel && (
                <button
                  onClick={() => setShowNewCarousel(false)}
                  className="px-4 py-2 text-white/70 hover:text-white transition-colors"
                >
                  Cancel
                </button>
              )}
              <button
                onClick={handleCreate}
                disabled={!newName.trim()}
                className="px-6 py-2 bg-gradient-to-r from-blue-500 to-purple-500 text-white rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50"
              >
                Create Carousel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
