/**
 * Element Migration Functions
 *
 * Converts existing slide structure to canvas elements.
 * Provides backward compatibility while enabling new canvas-based editing.
 *
 * @module lib/canvas/element-migration
 */

/**
 * Generate unique ID for canvas element
 */
function generateId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}
import { Slide, SlideContent } from '@/types/slide';
import { getContentValue, getContentPosition, hasPositionConfig, ImageConfig } from '@/types/slide-subtypes';
import { CanvasElement, TextElementData, ImageElementData, BackgroundElementData, DecoratorElementData, DecoratorType, CTAElementData } from '@/types/canvas-elements';
import { DecoratorConfig } from '@/types/decorators';

// Constants
const SLIDE_WIDTH = 1080;
const SLIDE_HEIGHT = 1350;

/**
 * Migrate headline from slide to canvas element
 *
 * Converts slide.content.headline to a TextElement.
 * Preserves positioning and styling.
 *
 * @param slide - The slide to migrate headline from
 * @returns CanvasElement for the headline, or null if no headline exists
 */
export function migrateHeadline(slide: Slide): CanvasElement | null {
  const headlineContent = slide.content.headline;

  if (!headlineContent) {
    return null;
  }

  // Get headline value (handle both string and PositionedContent)
  const headlineValue = typeof headlineContent === 'string'
    ? headlineContent
    : headlineContent.value;

  if (!headlineValue) {
    return null;
  }

  // Get position configuration
  const position = typeof headlineContent === 'object' && headlineContent.position
    ? headlineContent.position
    : undefined;

  // Calculate element position and size
  const { x, y, width, height, zIndex, alignment } = calculateElementPosition(
    position,
    'headline',
    headlineValue
  );

  // Get styling from slide style
  const styling = getSlideStyling(slide, 'headline');

  // Create TextElement
  const textElement: CanvasElement = {
    id: generateId('headline'),
    type: 'text',
    name: 'Headline',
    x,
    y,
    width,
    height,
    rotation: position?.rotation || 0,
    scaleX: 1,
    scaleY: 1,
    opacity: position?.opacity ?? 1,
    visible: true,
    locked: false,
    zIndex,
    data: {
      content: headlineValue,
      fontSize: styling.fontSize,
      fontFamily: styling.fontFamily,
      fontWeight: styling.fontWeight,
      color: styling.color,
      alignment: alignment as 'left' | 'center' | 'right',
      lineHeight: styling.lineHeight,
      letterSpacing: styling.letterSpacing,
      textDecoration: 'none',
      fontStyle: 'normal',
    } as TextElementData,
  };

  return textElement;
}

