/**
 * Migrate image from slide to canvas element
 *
 * Converts slide.content.imageConfig to an ImageElement.
 * Preserves all image settings including position, size, filters, borders, and effects.
 *
 * @param slide - The slide to migrate image from
 * @returns CanvasElement for the image, or null if no image exists
 */
export function migrateImage(slide: Slide): CanvasElement | null {
  const imageConfig = slide.content.imageConfig;

  if (!imageConfig || !imageConfig.imageUrl) {
    return null;
  }

  // Calculate image position and size based on position type
  const { x, y, width, height, zIndex } = calculateImagePosition(
    imageConfig.position,
    imageConfig.size
  );

  // Create ImageElement
  const imageElement: CanvasElement = {
    id: generateId('image'),
    type: 'image',
    name: 'Image',
    x,
    y,
    width,
    height,
    rotation: imageConfig.rotation || 0,
    scaleX: 1,
    scaleY: 1,
    opacity: imageConfig.opacity ?? 1,
    visible: true,
    locked: false,
    zIndex,
    data: {
      url: imageConfig.imageUrl,
      objectFit: imageConfig.objectFit,
      filters: {
        blur: imageConfig.filters?.blur,
        grayscale: imageConfig.filters?.grayscale,
        sepia: imageConfig.filters?.sepia,
        saturate: imageConfig.filters?.saturate,
        brightness: imageConfig.filters?.brightness,
        contrast: imageConfig.filters?.contrast,
        hueRotate: 0, // Not in ImageConfig
        invert: 0, // Not in ImageConfig
      },
      borderRadius: imageConfig.borderRadius || 0,
      borderWidth: imageConfig.borderWidth,
      borderColor: imageConfig.borderColor,
      shadow: imageConfig.shadow || false,
      blendMode: imageConfig.blendMode || 'normal',
    } as ImageElementData,
  };

  return imageElement;
}

